package tn.isetkebili.account.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(IllegalArgumentException.class) public ResponseEntity handleBadRequest(IllegalArgumentException ex) { return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("error", ex.getMessage())); } @ExceptionHandler(IllegalStateException.class) public ResponseEntity handleConflict(IllegalStateException ex) { return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", ex.getMessage())); } }
